public static int nextPrime(int desiredCapacity) {
    // Special case for small capacities
    if (desiredCapacity < 1000) {
        if (desiredCapacity < 4) {
            return 4;
        }
        if (desiredCapacity < 8) {
            return 8;
        }
        if (desiredCapacity < 16) {
            return 16;
        }
        return 32;
    }

    // Number of candidates to search for prime
    int numCandidates = 1 + desiredCapacity / 10;

    // Search for prime starting from the next odd number after desiredCapacity
    for (int i = 1 + desiredCapacity | 1; i < 2 * desiredCapacity; i += 2) {
        boolean isPrime = true;
        for (int j = 1; j < numCandidates && j * j <= i; j++) {
            if (i % j == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return i;
        }
    }
    // If all primes up to 10 times the desired capacity are not found, throw error
    throw new IllegalArgumentException("Could not find a prime number >= desired capacity");
}

