public final byte[] toByteArray() {
    // Create a byte array with the total size required to store all the content of the buffer(s)
    byte[] result = new byte[];
    // Iterate through all the buffers
    for (byte[] buffer : this) {
        // Copy the content of each buffer to the result array
        System.arraycopy(buffer, 0, result, 0, buffer.length);
    }
    // Return the completed result array
    return result;
}

